<?php
declare(strict_types=1);
require dirname(__DIR__).'/services/CodeLabService.php';
function clCheck(bool $ok,string $label):void {if(!$ok)throw new RuntimeException($label);}
function clReject(callable $fn,int $code,string $label):void {try{$fn();}catch(RuntimeException $e){clCheck($e->getCode()===$code,$label.' status');return;}throw new RuntimeException($label);}
$db=new PDO('sqlite::memory:');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);
$sql=file_get_contents(dirname(__DIR__).'/database/migrations/054_code_lab.sql');
$sql=str_replace('BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY','INTEGER PRIMARY KEY AUTOINCREMENT',$sql);
$sql=preg_replace('/,\s*INDEX code_lab_server \(server_id, id\)/','',$sql);
$sql=str_replace(['UNIQUE KEY code_lab_private_attempt','UNIQUE KEY code_lab_private_playground'],['UNIQUE','UNIQUE'],$sql);
$sql=preg_replace('/\) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;/',');',$sql);$db->exec($sql);
$db->exec('CREATE TABLE users(id INTEGER PRIMARY KEY,role TEXT,deleted_at TEXT,full_name TEXT,username TEXT,status TEXT DEFAULT "active");CREATE TABLE servers(id INTEGER PRIMARY KEY,name TEXT,owner_id INTEGER,status TEXT);CREATE TABLE server_members(server_id INTEGER,user_id INTEGER)');
$db->exec("INSERT INTO users (id,role,deleted_at,full_name,username) VALUES(1,'facilitator',NULL,'Teacher','teacher'),(2,'student',NULL,'Alice','alice'),(3,'student',NULL,'Bob','bob'),(4,'student',NULL,'Other','other'),(5,'student',NULL,'Owner','owner');INSERT INTO servers VALUES(1,'Course',1,'active'),(2,'Other course',1,'active'),(3,'Student owned',5,'active');INSERT INTO server_members VALUES(1,1),(1,2),(1,3),(2,4),(3,5)");
$now=strtotime('2026-10-20T00:00:00Z');$service=new CodeLabService($db,fn()=>$GLOBALS['now']);
$input=['title'=>'Loops','instructions'=>'Sum inputs','language'=>'python','kind'=>'assignment','starter_code'=>'# Start here','duration_minutes'=>60];
clReject(fn()=>$service->create(1,2,$input),403,'Students cannot create tasks');
clReject(fn()=>$service->create(3,5,$input),403,'Student server ownership does not grant grading');
$tid=$service->create(1,1,$input)['id'];
$a=$service->start(1,2,$tid);$b=$service->start(1,3,$tid);
clCheck($a['attempt']['id']!==$b['attempt']['id'],'Separate attempt ids');
clCheck($service->start(1,2,$tid)['attempt']['id']===$a['attempt']['id'],'Repeated start resumes same attempt');
$a=$service->save(1,2,$tid,['code'=>'print(42)','version'=>1,'user_id'=>3]);
clCheck($service->start(1,3,$tid)['attempt']['code']==='# Start here','Forged student id cannot modify another student');
clReject(fn()=>$service->save(1,2,$tid,['code'=>'old','version'=>1]),409,'Stale tab cannot overwrite new code');
clReject(fn()=>$service->start(2,4,$tid),404,'Cross-server task rejected');
clReject(fn()=>$service->start(1,4,$tid),403,'Nonmember access rejected');
clReject(fn()=>$service->submissions(1,2,$tid),403,'Students cannot list submissions');
clCheck($service->submissions(1,1,$tid)===[],'Facilitator review excludes private drafts');
$a=$service->save(1,2,$tid,['code'=>'print(42)','version'=>2],true);
clCheck($a['attempt']['state']==='submitted','Submitted state');
clReject(fn()=>$service->save(1,2,$tid,['code'=>'modified','version'=>3]),403,'Submitted source immutable');
clCheck(count($service->submissions(1,1,$tid))===1,'Only submitted work visible');
clReject(fn()=>$service->review(1,2,$tid,['student_id'=>2,'score'=>100]),403,'Student cannot grade');
clReject(fn()=>$service->review(1,1,$tid,['student_id'=>3,'score'=>100]),404,'Cannot grade private draft');
$service->review(1,1,$tid,['student_id'=>2,'score'=>85,'feedback'=>'Good work']);
clCheck((int)$service->start(1,2,$tid)['attempt']['score']===85,'Student can see own review');
$now+=3600;
clReject(fn()=>$service->save(1,3,$tid,['code'=>'late','version'=>1]),403,'Timer enforced at server boundary');
clCheck($service->start(1,3,$tid)['attempt']['state']==='expired','Expired draft readable');
$timed=$input;$timed['due_at']='2026-10-20T01:05:00.000Z';$tid2=$service->create(1,1,$timed)['id'];$t=$service->start(1,2,$tid2);
clCheck($t['attempt']['ends_at']===$now+300,'Deadline wins over personal timer');$now+=300;
clReject(fn()=>$service->save(1,2,$tid2,['code'=>'late','version'=>1],true),403,'Exact deadline rejects submission');
$future=$input;$future['opens_at']='2026-10-21T00:00:00.000Z';$futureId=$service->create(1,1,$future)['id'];clReject(fn()=>$service->start(1,2,$futureId),403,'Opening time enforced');
$free=$input;$free['duration_minutes']=null;$free['kind']='practice';$freeId=$service->create(1,1,$free)['id'];$service->start(1,2,$freeId);$now+=86400*30;
clCheck($service->save(1,2,$freeId,['code'=>'still working','version'=>1])['attempt']['state']==='in_progress','No deadline and no timer remain open');
$service->playground(1,2,'python',['code'=>'private','version'=>0]);
clCheck($service->playground(1,3,'python')['code']==='','Playground student isolation');
clCheck($service->playground(1,2,'java')['code']==='','Playground language isolation');
clReject(fn()=>$service->playground(1,2,'python',['code'=>'overwrite','version'=>0]),409,'Playground insert race protection');
clReject(fn()=>$service->playground(1,4,'python'),403,'Playground membership required');
$bad=$input;$bad['due_at']='2026-02-30T00:00:00Z';clReject(fn()=>$service->create(1,1,$bad),400,'Invalid calendar date');
$bad=$input;$bad['language']='shell';clReject(fn()=>$service->create(1,1,$bad),400,'Unsupported runtime rejected');
$db->exec("UPDATE users SET status='banned' WHERE id=3");clReject(fn()=>$service->start(1,3,$tid),403,'Banned account loses access');
$db->exec('DELETE FROM server_members WHERE user_id=2 AND server_id=1');clReject(fn()=>$service->start(1,2,$tid),403,'Removed member loses attempt access');
echo "PASS: private attempts, playground isolation, roles, cross-server access, submission locking, deadlines, timing and stale saves\n";
